@RestControllerAdvice class Problems extends ResponseEntityExceptionHandler {@Override protected ResponseEntity<Object> handleMethodArgumentNotValid(MethodArgumentNotValidException exception,HttpHeaders headers,HttpStatusCode status,WebRequest request){var problem=ProblemDetail.forStatusAndDetail(HttpStatus.BAD_REQUEST,"Sprawdź dane formularza");Map<String,List<String>> errors=exception.getBindingResult().getFieldErrors().stream().collect(Collectors.groupingBy(error->error.getField(),LinkedHashMap::new,Collectors.mapping(error->Objects.requireNonNullElse(error.getDefaultMessage(),"Nieprawidłowa wartość"),Collectors.toList())));problem.setProperty("errors",errors);return ResponseEntity.badRequest().contentType(MediaType.APPLICATION_PROBLEM_JSON).body(problem);}}

